// Fails when frontend code uses a color that bypasses the theme in
// resources/css/app.css: raw Tailwind palette classes (bg-red-600,
// text-white…) or color literals (#hex, rgb(), hsl(), oklch()).
// Add a theme variable instead, or allowlist a deliberate exception below.

import { readdirSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';

const ROOT = new URL('..', import.meta.url).pathname;
const SCAN = 'resources/js';
// Generated by Wayfinder; never hand-written.
const SKIP_DIRS = [
    'resources/js/actions',
    'resources/js/routes',
    'resources/js/wayfinder',
];

// file → exact matches allowed there
const ALLOW = {
    // shadcn modal scrims: a dimmed backdrop, the same in every theme.
    'resources/js/components/ui/dialog/DialogOverlay.vue': ['bg-black/80'],
    'resources/js/components/ui/dialog/DialogScrollContent.vue': [
        'bg-black/80',
    ],
    'resources/js/components/ui/sheet/SheetOverlay.vue': ['bg-black/80'],
};

const PALETTE =
    'slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose|black|white';
const UTILITY =
    'bg|text|border(?:-[trblxyse])?|ring|ring-offset|outline|fill|stroke|from|via|to|divide|decoration|placeholder|shadow|accent|caret';

const PATTERNS = [
    new RegExp(
        `(?<![\\w-])(?:${UTILITY})-(?:${PALETTE})(?:-\\d{2,3})?(?:/\\d+)?(?![\\w-])`,
        'g',
    ),
    /(?<=['"`[(\s:,])#(?:[0-9a-fA-F]{8}|[0-9a-fA-F]{6}|[0-9a-fA-F]{3,4})(?![\w-])/g,
    /\b(?:rgba?|hsla?|oklch|oklab|lab|lch)\(/g,
];

function* walk(dir) {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
        const path = join(dir, entry.name);
        const rel = relative(ROOT, path);

        if (entry.isDirectory()) {
            if (!SKIP_DIRS.includes(rel)) {
                yield* walk(path);
            }
        } else if (/\.(vue|ts)$/.test(entry.name)) {
            yield rel;
        }
    }
}

const problems = [];

for (const file of walk(join(ROOT, SCAN))) {
    const allowed = ALLOW[file] ?? [];
    const lines = readFileSync(join(ROOT, file), 'utf8').split('\n');

    lines.forEach((line, i) => {
        for (const pattern of PATTERNS) {
            for (const [match] of line.matchAll(pattern)) {
                if (!allowed.includes(match)) {
                    problems.push(`${file}:${i + 1}  ${match}`);
                }
            }
        }
    });
}

if (problems.length > 0) {
    console.error(
        'Hardcoded colors found; use a theme variable from resources/css/app.css:\n',
    );
    console.error(problems.map((p) => `  ${p}`).join('\n'));
    process.exit(1);
}

console.log('No hardcoded colors.');
